local ok, res = pcall(function() local F = _G.DERPY_FOLLOW local o = {} for _, e in ipairs(F.zlog) do o[#o + 1] = math.floor(e[1] * 100) / 100 .. ":" .. math.floor(e[2] * 1000) / 1000 end return {on = F.on, stopped = F.stopped, err = F.err, unit = F.unit_name, utype = F.utype, zooms = _G.DERPY_ZOOM, zoom = F.zoom, log = table.concat(o, " "), zoom_from = F.zoom_from, frames = F.frames, fought = F.fought} end) if ok then return res end return "ERR " .. tostring(res)
